B.acV=new A.bn("M\u1ee5c \u0111\xe3 l\u01b0u, hi\u1ec7n v\u1eadt v\u1eeba m\u1edf v\xe0 k\u1ebft qu\u1ea3 th\u1eed t\xe0i m\u1eabu ch\u1ec9 gi\u1eef trong phi\xean. L\u01b0\u1ee3t tham quan, \u0111\u01a1n h\xe0ng, \u0111i\u1ec3m v\xe0 huy hi\u1ec7u \u0111\u01b0\u1ee3c t\u1ea3i t\u1eeb h\u1ec7 th\u1ed1ng.",B.K,null)
B.acW=new A.bn("N\u1ebfu \u0111\u1ed9 t\u01b0\u01a1ng \u0111\u1ed3ng ch\u01b0a \u0111\u1ee7 cao, h\u1ec7 th\u1ed1ng s\u1ebd \u0111\u1ec1 ngh\u1ecb x\xe1c nh\u1eadn ho\u1eb7c khuy\u1ebfn ngh\u1ecb qu\xe9t m\xe3 QR c\u1ea1nh hi\u1ec7n v\u1eadt.",B.K,null)
